  "CREATE TABLE IF NOT EXISTS cly (uuid TEXT PRIMARY KEY, start INTEGER NOT NULL, end INTEGER NOT NULL, status TEXT NOT NULL, upd TEXT, created INTEGER, data TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 1, fetched INTEGER NOT NULL)",
  // version 21: the devices that get the notifications, and the visits being watched for them
  "CREATE TABLE IF NOT EXISTS push (ep TEXT PRIMARY KEY, p256dh TEXT NOT NULL, auth TEXT NOT NULL, ua TEXT, created INTEGER NOT NULL, ok INTEGER, fails INTEGER NOT NULL DEFAULT 0)",
