const KICK = ["k_legal", "k_contact", "k_social", "k_count", "k_list", "k_photos", "k_carrier", "k_rates", "k_time", "k_returns", "k_pack", "k_pay", "k_bizum", "k_stock", "k_brand", "k_refs", "k_zone", "k_ads", "k_budget", "k_emails", "k_launch", "k_dates", "k_next"];
const TAGS = ["", "web", "assistant", "crm", "team"];
const LINKS = ["web", "assistant", "crm"];                 // where each finished piece lives, once there is something to open
// own content: its blocks, the id of a built-in idea (block-position) and of one Chris adds
const CBLK = ["b1", "b2", "b3", "b4", "b5", "b6", "b7", "b8", "b9", "enc"], CIDEA = /^(b[1-9]|enc)-[0-9]{1,3}$/, CCUST = /^ci_[A-Za-z0-9_-]{6,20}$/;
// every place a video of ours can sit in the portal
const VIDS = ["welcome", "plan", "call", "wa", "meta", "google", "domain", "site", "brand", "shoot", "brief", "d_content", "d_web", "d_assistant", "d_crm", "portals"];   // in the order the client meets them; every key of ACCESS is here
// The videos to record for the portal (v43: only three; the accesses are done together on the kick-off call and each step has its
// written instructions): slot, group, title, what it is for, the script line by line, how to shoot it and how long. The other slots
// stay available in Settings for a step where clients get stuck; a slot with no video is invisible to the client.
