/* ---------- a small PDF writer, enough for an invoice: text in two weights, hairlines and bars, on A4 pages ----------
   It uses the two standard fonts every PDF reader carries (Helvetica and its bold), so nothing has to be embedded and the file
   stays at a few kilobytes. Text is limited to the Windows Latin set (Spanish and English are whole; what it lacks prints as "?"). */
function pdfBytes(s) {
  const out = [];
  for (const ch of String(s == null ? "" : s)) { const c = ch.codePointAt(0); out.push((c >= 32 && c <= 126) || (c >= 160 && c <= 255) ? c : CP[c] || (c === 9 ? 32 : 63)); }
  return out;
}
const pdfW = (b, bold, size) => { const t = bold ? HWB : HW; let w = 0; for (const c of b) w += t[c - 32] || 0; return (w * size) / 1000; };
const pdfLit = (b) => { let s = "("; for (const c of b) s += c === 40 || c === 41 || c === 92 ? "\\" + String.fromCharCode(c) : c > 126 ? "\\" + c.toString(8).padStart(3, "0") : String.fromCharCode(c); return s + ")"; };
