const LQ_JS = "(function(){var d=document.documentElement;d.classList.add('lq-in');setTimeout(function(){d.classList.add('lq-done')},1600);\nif(matchMedia('(prefers-reduced-motion: reduce)').matches)return;var S='.kpi,.ini-c,.board .card',raf=0,ev=null;\ndocument.addEventListener('pointermove',function(e){ev=e;if(raf)return;raf=requestAnimationFrame(function(){raf=0;var t=ev.target&&ev.target.closest&&ev.target.closest(S);if(!t)return;var r=t.getBoundingClientRect();t.style.setProperty('--mx',(ev.clientX-r.left)+'px');t.style.setProperty('--my',(ev.clientY-r.top)+'px')})},{passive:true})})();\n";
const skin = (h) => { const lq = String(h).indexOf('id="sh404"') > -1; return String(h).replace(/<meta name="theme-color"[^>]*>/g, "").replace("</head>", '<meta name="theme-color" content="' + (lq ? "#F6F7F3" : "#0A120F") + '"><style id="t404">' + THEME_404 + "</style>" + (lq ? '<style id="t404l">' + LIGHT_404 + "</style>" : "") + "</head>").replace(/<\/body>(?![\s\S]*<\/body>)/, lq ? "<script>" + LQ_JS + "</script></body>" : "</body>"); };
const shell = (h) => h.replace("</head>", '<style id="sh404">' + SHELL_CSS + "</style></head>").replace(/<\/body>(?![\s\S]*<\/body>)/, "<script>" + MAP_404 + "</script><script>" + SHELL_JS + "</script></body>");
const page = (html, status) => new Response(skin(html), { status: status || 200, headers: Object.assign({ "content-type": "text/html; charset=utf-8", "content-security-policy": CSP }, SEC) });
const go = (to) => new Response("", { status: 302, headers: Object.assign({ location: to }, SEC) });
const bad = (code, status) => json({ error: code }, status || 400);

function origins(env) { return env.DEV ? [SITE, env.DEV] : [SITE]; }
// the session cookie: bound to this host only, unreadable from script, sent over https only (plain http just on a developer's own machine)
const cname = (env) => (env.DEV ? "s404dev" : "__Host-s404");
function cookieOf(req, env) { const m = new RegExp("(?:^|;\\s*)" + cname(env) + "=([A-Za-z0-9_-]{20,80})").exec(req.headers.get("cookie") || ""); return m ? m[1] : ""; }
