async function session(req, env) {
  const t = cookieOf(req, env); if (!t) return null;
  const r = await env.DB.prepare("SELECT u.id, u.email, u.role, u.client_id, s.expires FROM sessions s JOIN users u ON u.id = s.uid WHERE s.h = ?1 AND u.disabled = 0").bind(await sha(t)).first();
  if (!r || r.expires < Date.now()) return null;
  return r;
}
