const invDmy = (s) => (/^\d{4}-\d{2}-\d{2}$/.test(s || "") ? Number(s.slice(8, 10)) + "/" + Number(s.slice(5, 7)) + "/" + s.slice(0, 4) : "");
function invEur(c, cur) {
  const p = (Math.abs(c) / 100).toFixed(2).split("."), i = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return (c < 0 ? "−" : "") + i + "," + p[1] + " " + (!cur || cur === "EUR" ? "€" : cur);
}
