const BOT_MILE = { kickoff: "Llamada de arranque", access: "Accesos y tu tienda", web: "Diseño de tu tienda", assistant: "Catálogo", crm: "Pagos, envíos y stock", tests: "Pedido de prueba", live: "Lanzamiento" };
const BOT_ST = { pending: "pendiente", doing: "en marcha", done: "hecho", client_done: "hecho por el cliente, falta revisarlo", verified: "comprobado" };
const PCHAT_DAY = 40;
async function pchatCtx(env, cid) {
  const c = await clientFull(env, cid); if (!c) return null;
  const pl = c.plan, mt = {}; if (pl && pl.miles) for (const m of pl.miles) mt[m.k] = m.t;
  const today = new Date(Date.now() + 3600000).toISOString().slice(0, 10), n = c.start_date ? Math.floor((Date.parse(today) - Date.parse(c.start_date)) / DAY) : null;   // day 0 is the start, as in the portal
  const inv = await cinvList(env, cid), docs = await cdocList(env, cid);
  const L = [];
  L.push("Cliente: " + c.name + (c.contact && c.contact.name ? " (la persona con la que hablas: " + c.contact.name + ")" : "") + (c.sector ? " · sector: " + c.sector : "") + ".");
  L.push(c.start_date ? (n < 0 ? "Empieza el " + c.start_date + " (faltan " + (-n) + " días)." : n <= 15 ? "Hoy es el día " + n + " de 15 (empezó el " + c.start_date + ")." : "Empezó el " + c.start_date + "; ya pasó el día 15 (hoy es el día " + n + ").") : "Aún no tiene día de arranque fijado.");
  if (c.kcall && c.kcall.at) L.push("Llamada de arranque: " + new Date(c.kcall.at).toLocaleString("es-ES", { timeZone: CAL_TZ, weekday: "long", day: "numeric", month: "long", hour: "2-digit", minute: "2-digit" }) + (c.kcall.at < Date.now() ? " (ya hecha)." : "."));
  else L.push("Aún no ha agendado la llamada de arranque (se agenda desde el Inicio del portal).");
  L.push("Etapas: " + c.miles.map((m) => (mt[m.key] || BOT_MILE[m.key] || m.key) + " — " + (BOT_ST[m.status] || m.status)).join("; ") + ".");
  const accP = c.access.filter((a) => a.status === "pending").length; if (c.access.length) L.push("Accesos: " + (c.access.length - accP) + " de " + c.access.length + " dados.");
  const rv = (c.reviews || []).filter((r) => r.status === "pending"); if (rv.length) L.push("Tiene pendiente revisar: " + rv.map((r) => "«" + r.title + "»").join(", ") + ".");
  if (c.updates && c.updates.length) L.push("Últimas novedades que le hemos publicado: " + c.updates.slice(0, 4).map((u) => new Date(u.ts).toISOString().slice(0, 10) + ": " + u.text.slice(0, 220)).join(" | "));
  L.push(inv.length ? "Facturas en su portal: " + inv.map((f) => "n.º " + f.num + " del " + f.date + " por " + (f.total / 100).toFixed(2).replace(".", ",") + " " + f.cur).join("; ") + "." : "Todavía no tiene facturas en el portal.");
  L.push(docs.some((d) => d.kind === "contract") ? "Su contrato está subido en «Contrato y facturas»." : "Su contrato todavía no está subido al portal.");
  if (c.preview_url) L.push("Enlace para ver su tienda en construcción: " + c.preview_url);
  const faq = pl && pl.text && pl.text.faq; if (faq && faq.length) L.push("Preguntas frecuentes de su portal: " + faq.map((f) => f[0] + " → " + f[1]).join(" | "));
  return { c: c, text: L.join("\n") };
}
