async function sendMail(env, to, subject, html, text) {
  const key = await getMeta(env, "nl_key"); if (!key) return { ok: false, why: "nomail" };
  try {
    const r = await fetch((env.MAILAPI || "https://api.resend.com") + "/emails", { method: "POST", headers: { authorization: "Bearer " + key, "content-type": "application/json" }, body: JSON.stringify({ from: VSL_FROM, to: [to], reply_to: VSL_REPLY, subject, html, text }), signal: AbortSignal.timeout(8000) });
    return { ok: r.ok, why: r.ok ? "" : "mail" };
  } catch (e) { return { ok: false, why: "mail" }; }
}

