async function rsPost(req, env, b) {
  await v48Ready(env);
  const id = await rsCheck(env, b.v); if (!id) return bad("link", 403);
  const DBq = env.DB, l = await DBq.prepare("SELECT * FROM ll WHERE id = ?1").bind(id).first(); if (!l) return bad("missing", 404);
  const now = Date.now(); if (l.cx) return bad("cancelled", 409); if (l.start && l.start < now) return bad("past", 409);
  let t = null; try { t = await gTok(env); } catch (e) { t = null; } if (!t) return json({ error: "nocal" }, 503);
  const calId = l.inv ? "ev_" + (await sha("b|" + l.inv)).slice(0, 12) : "", first = String(l.name || "").split(" ")[0], was = l.start ? vslWhen(new Date(l.start).toISOString(), CAL_TZ) : "";
  if (b.cancel === true) {
    if (l.inv) { try { await gApi(t, "/calendars/primary/events/" + encodeURIComponent(l.inv) + "?sendUpdates=all", { method: "DELETE" }); } catch (e) {} }
    const st = [DBq.prepare("UPDATE ll SET cx = 1, upd = ?2 WHERE id = ?1").bind(id, now)];
    if (calId) st.push(DBq.prepare("DELETE FROM cal WHERE id = ?1").bind(calId), DBq.prepare("DELETE FROM gsync WHERE cid = ?1").bind(calId));
    await DBq.batch(st); await setMeta(env, "gb_slots", ""); await setMeta(env, "vsl_slots", "");
    try { await pushAll(env, { title: "Ha cancelado la llamada · " + l.name, body: (l.biz || "") + " · era el " + was + ". Desde el enlace del email.", tag: "lb" + id, url: "/admin/landing#l=" + id }); } catch (e) {}
    return json({ ok: true, cancelled: true });
  }
  const s = Date.parse(typeof b.start === "string" ? b.start : ""); if (!s) return bad("start");
  const slots = await gbSlots(env, true); if (!slots.some((x) => Date.parse(x) === s)) return json({ error: "taken", slots: slots.filter((x) => Date.parse(x) !== l.start) }, 409);
  const e = s + GB_DUR * 60000, C = CalCore;
  let gu = "";
  if (l.inv) { const ev = await gApi(t, "/calendars/primary/events/" + encodeURIComponent(l.inv) + "?sendUpdates=all", { method: "PATCH", body: JSON.stringify({ start: { dateTime: new Date(s).toISOString(), timeZone: CAL_TZ }, end: { dateTime: new Date(e).toISOString(), timeZone: CAL_TZ } }) }); gu = ev.updated || ""; }
  const st = [DBq.prepare("UPDATE ll SET start = ?2, r24 = 0, r1 = 0, ap = 0, upd = ?3 WHERE id = ?1").bind(id, s, now)];
  if (calId) st.push(DBq.prepare("UPDATE cal SET start = ?2, end = ?3, updated = ?4 WHERE id = ?1").bind(calId, C.fromUTC(s, CAL_TZ), C.fromUTC(e, CAL_TZ), now), DBq.prepare("UPDATE gsync SET st = ?2, au = ?3, gu = ?4 WHERE cid = ?1").bind(calId, s, now, gu));
  try { await DBq.batch(st); } catch (er) { await DBq.batch(st.slice(0, 1)); }
  await setMeta(env, "gb_slots", ""); await setMeta(env, "vsl_slots", "");
  const whenTxt = vslWhen(new Date(s).toISOString(), CAL_TZ), join = l.join_url || "";
  const gcal = "https://calendar.google.com/calendar/render?action=TEMPLATE&text=" + encodeURIComponent("Llamada con Christian · 404 Growth") + "&dates=" + icsDate(s) + "/" + icsDate(e) + "&details=" + encodeURIComponent("Tu tienda online en 15 días." + (join ? "\nVideollamada: " + join : "")) + "&location=" + encodeURIComponent(join || "Google Meet");
  const mm = vslMail({ name: l.name, met: SITE + "/metodo?c=" + id }, whenTxt, join, gcal, await rsLink(env, id));
  await sendMail(env, l.email, "Nueva hora: tu llamada con Christian · " + whenTxt, mm.html, mm.text);
  try { await pushAll(env, { title: "Ha cambiado la hora · " + l.name, body: (l.biz || "") + " · ahora el " + whenTxt + " (antes el " + was + ").", tag: "lb" + id, url: "/admin/landing#l=" + id }); } catch (er) {}
  return json({ ok: true, start: new Date(s).toISOString(), when: whenTxt });
}

/* ---------- every minute: reminders before the call, the notice to mark who came, the ad spend ---------- */
async function callCron(env) {
  await v48Ready(env);
  const now = Date.now(), DBq = env.DB;
  const rows = (await DBq.prepare("SELECT * FROM ll WHERE bk = 1 AND COALESCE(cx, 0) = 0 AND start IS NOT NULL AND start > ?1 AND start < ?2 LIMIT 40").bind(now - 4 * 3600000, now + 25 * 3600000).all()).results || [];
  for (const l of rows) {
    const left = l.start - now, first = String(l.name || "").split(" ")[0], when = vslWhen(new Date(l.start).toISOString(), CAL_TZ), join = l.join_url || "";
    if (!l.r24 && left <= 24 * 3600000 && left > 3 * 3600000) {
      await DBq.prepare("UPDATE ll SET r24 = 1 WHERE id = ?1").bind(l.id).run();
      if ((l.bk_at || l.ts) < now - 6 * 3600000) {
        const rs = await rsLink(env, l.id), met = SITE + "/metodo?c=" + l.id;
        await sendMail(env, l.email, "Mañana hablamos · " + when, mailShell("Mañana hablamos, " + first + ".", [
          { html: '<div style="background:#EEF5F2;border-radius:14px;padding:16px 18px"><div style="font-size:13px;color:#5B6762">Cuándo</div><div style="font-size:18px;font-weight:700">' + vslEsc(when.charAt(0).toUpperCase() + when.slice(1)) + " (hora de España)</div><div style=\"font-size:13px;color:#5B6762;margin-top:8px\">Dónde</div><div style=\"font-size:16px;font-weight:600\">Google Meet · " + GB_DUR + " minutos</div></div>" },
          "Para aprovecharla, ten a mano tu web o tu Instagram, más o menos cuántos productos tienes y qué TPV usas. Si te apetece, antes mira los vídeos cortos con las dudas de siempre."],
          [[join, "Entrar a la llamada", true], [met, "Ver los vídeos", false]], "¿Te ha surgido algo? Cambia la hora aquí: " + rs),
          "Mañana hablamos, " + first + ".\n\nCuándo: " + when + " (hora de España)\nGoogle Meet: " + (join || "en la invitación") + "\n\nLos vídeos antes de la llamada: " + met + "\n¿Te ha surgido algo? Cambia la hora: " + rs + "\n\nUn abrazo,\nChristian");
      }
    }
    if (!l.r1 && left <= 65 * 60000 && left > 5 * 60000) {
      await DBq.prepare("UPDATE ll SET r1 = 1 WHERE id = ?1").bind(l.id).run();
      const rs = await rsLink(env, l.id);
      await sendMail(env, l.email, "En 1 hora hablamos · " + new Intl.DateTimeFormat("es-ES", { timeZone: CAL_TZ, hour: "2-digit", minute: "2-digit" }).format(new Date(l.start)), mailShell("En una hora nos vemos, " + first + ".", [
        "Te espero en Google Meet a las " + new Intl.DateTimeFormat("es-ES", { timeZone: CAL_TZ, hour: "2-digit", minute: "2-digit" }).format(new Date(l.start)) + ". Son " + GB_DUR + " minutos: me cuentas tu tienda y te enseño cómo quedaría online."],
        [[join, "Entrar a la llamada", true]], "¿No llegas? Cambia la hora aquí: " + rs),
        "En una hora nos vemos, " + first + ".\n\nGoogle Meet: " + (join || "en la invitación") + "\n¿No llegas? Cambia la hora: " + rs + "\n\nUn abrazo,\nChristian");
    }
    if (!l.ap && l.att === null && now > l.start + (GB_DUR + 15) * 60000) {
      await DBq.prepare("UPDATE ll SET ap = 1 WHERE id = ?1").bind(l.id).run();
      try { await pushAll(env, { title: "¿Vino " + first + "?", body: (l.biz || "") + " · márcalo en Landing (asistió, cualificado, cliente) para saber qué anuncio trae ventas.", tag: "ap" + l.id, url: "/admin/landing#l=" + l.id }); } catch (e) {}
    }
  }
  const last = parse(await getMeta(env, "meta_ads_last"), null);
  if (!last || now - last.at > 3 * 3600000) { const cfg = await metaCfg(env); if (cfg.act && (await getMeta(env, "meta_ads"))) await adsPull(env, last && last.ok ? 3 : 30); }
}
