let lpatched = false;
async function patchOnce(env) {   /* v68: changes to leads that are already in the CRM, applied once (json_patch) */
  if (lpatched || !LEAD_PATCH.length || (env.DEV && !env.SEED_LOCAL)) return;
  try {
    if (await env.DB.prepare("SELECT v FROM meta WHERE k = ?1").bind(LEAD_PATCH_KEY).first()) { lpatched = true; return; }
    const now = Date.now();
    const st = LEAD_PATCH.map(([id, p]) => env.DB.prepare("UPDATE docs SET data = json_patch(data, ?2), updated = ?3 WHERE coll = 'leads' AND id = ?1").bind(id, JSON.stringify(p), now));
    st.push(env.DB.prepare("INSERT INTO meta (k, v) VALUES (?1, ?2) ON CONFLICT(k) DO NOTHING").bind(LEAD_PATCH_KEY, String(LEAD_PATCH.length)));
    st.push(env.DB.prepare("INSERT INTO meta (k, v) VALUES ('crm_rev', '1') ON CONFLICT(k) DO UPDATE SET v = CAST(CAST(v AS INTEGER) + 1 AS TEXT)"));
    await env.DB.batch(st);
    lpatched = true;
  } catch (e) { /* tried again on the next request */ }
}
let seeded = false;
async function seedOnce(env) {
  if (seeded || !SEED.length || (env.DEV && !env.SEED_LOCAL)) return;
  try {
    if (await env.DB.prepare("SELECT v FROM meta WHERE k = ?1").bind(SEED_KEY).first()) { seeded = true; return; }
    const ids = SEED.map((x) => x[0]);
    const have = new Set(((await env.DB.prepare("SELECT id FROM docs WHERE coll = 'leads' AND id IN (SELECT value FROM json_each(?1))").bind(JSON.stringify(ids)).all()).results || []).map((r) => r.id));
    const top = await env.DB.prepare("SELECT COALESCE(MAX(CAST(json_extract(data, '$.order') AS INTEGER)), 0) AS m FROM docs WHERE coll = 'leads'").first();
    let o = Number(top && top.m) || 0; const now = Date.now(), st = [];
    for (const [id, d] of SEED) {
      if (have.has(id)) continue;
      o++; st.push(env.DB.prepare("INSERT INTO docs (coll, id, data, updated) VALUES ('leads', ?1, ?2, ?3) ON CONFLICT(coll, id) DO NOTHING").bind(id, JSON.stringify(Object.assign({}, d, { order: o })), now));
    }
    st.push(env.DB.prepare("INSERT INTO meta (k, v) VALUES (?1, ?2) ON CONFLICT(k) DO NOTHING").bind(SEED_KEY, String(st.length)));
    st.push(env.DB.prepare("INSERT INTO meta (k, v) VALUES ('crm_rev', '1') ON CONFLICT(k) DO UPDATE SET v = CAST(CAST(v AS INTEGER) + 1 AS TEXT)"));
    await env.DB.batch(st);
    seeded = true;
  } catch (e) { /* the admin keeps working; it is tried again on the next request */ }
}

