const SOC_PILLARS = ["De tienda física a tienda online: el error que más ventas le quita a una tienda física", "Números claros: qué cuesta y qué deja vender online siendo tienda física", "Anuncios de Meta para que una tienda de barrio venda online en toda España", "Email marketing: la recompra online que ninguna tienda física trabaja", "Stock, envíos y devoluciones: vender online sin que la tienda física se resienta", "Lo que se vende bien online según el tipo de tienda física", "Lo que cambia (y lo que no) cuando una tienda física empieza a vender online"];   // v55: everything about physical → online
const slugify = (t) => String(t || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80) || "entrada";
async function blogSlug(env, base, own) { let s = slugify(base), n = 1; while (true) { const r = await env.DB.prepare("SELECT slug FROM lpost WHERE slug = ?1").bind(n === 1 ? s : s + "-" + n).first(); if (!r || r.slug === own) return n === 1 ? s : s + "-" + n; n++; } }
async function liDraft(env, auto) {
  const prev = (await env.DB.prepare("SELECT title, kw FROM lpost ORDER BY created DESC LIMIT 40").all()).results;
  const used = new Set(prev.map((r) => (r.kw || "").toLowerCase()));
  // v55: the keywords marked «idea» in SEO (the plan of seo/palabras-clave.json) go first, in order; each article links once to the page its keyword belongs to
  let kws = []; try { kws = (await env.DB.prepare("SELECT id, kw, intent, page FROM keywords WHERE status = 'idea' ORDER BY updated DESC LIMIT 80").all()).results.filter((k) => !used.has(k.kw.toLowerCase()) && /tienda|online|ecommerce|e-commerce|shopify|vender|venta|email|anuncio|ads|carrito|comercio|cat[aá]logo|envio|env[ií]o|producto|instagram|tiktok|google|marketplace|amazon|bizum|pago|dominio|navidad|black friday|clientes|rese[ñn]as|whatsapp|fotograf|ropa|joy|vino|regalo|devoluc/i.test(k.kw)); } catch (e) { kws = []; }
  const n = Math.floor(Date.now() / 864e5), pillar = SOC_PILLARS[n % SOC_PILLARS.length], pick = kws[0] || null, kw = pick ? pick.kw : "", link = pick && /^\/[a-z0-9\/-]*$/.test(pick.page || "") ? pick.page : "";
  let hooks = []; try { const ids = await igIds(env, "404"); const rows = (ids.length ? (await env.DB.prepare("SELECT data FROM igm WHERE acct IN (" + ids.map((_, i) => "?" + (i + 1)).join(",") + ") ORDER BY ts DESC LIMIT 120").bind(...ids).all()).results : []).map((r) => JSON.parse(r.data)).filter((d) => d.ins && d.ins.reach && d.cap); if (rows.length >= 6) { const sc = igScore(rows); hooks = rows.map((d, i) => [sc[i], d.cap.split("\n")[0].slice(0, 140)]).sort((a, b) => b[0] - a[0]).slice(0, 5).map((x) => x[1]); } } catch (e) { hooks = []; }
  const out = await socAI(env, SOC_VOICE,
    "Escríbeme el post de LinkedIn de hoy y el artículo del blog que lo acompaña.\n\nTema del día: «" + pillar + "»." + (kw ? "\nPalabra clave SEO para el artículo: «" + kw + "» (en el título, en la entradilla y en un subtítulo, sin forzarla). El artículo es para el dueño de una tienda física que quiere vender online o que ya vende y quiere vender más." : "\nElige tú una búsqueda concreta que haría en Google un dueño de tienda física que quiere vender online, y úsala como palabra clave.") +
    (link ? "\nEn el artículo, enlaza una vez y con naturalidad a esta página de 404growth.com, en Markdown: [texto que describa la página](" + link + ")." : "") +
    (prev.length ? "\nNo repitas estos temas ya publicados: " + prev.slice(0, 25).map((r) => "«" + r.title + "»").join(", ") + "." : "") +
    (hooks.length ? "\nPrimeras frases de mis publicaciones de Instagram que mejor han funcionado (para el tono del gancho, no para copiarlas): " + hooks.map((h) => "«" + h + "»").join(" · ") + "." : "") +
    "\n\nEl post: gancho en la primera línea de menos de 12 palabras, líneas cortas con aire, 900-1.300 caracteres, termina con una pregunta o una invitación suave a escribirme; como mucho 3 hashtags al final; sin enlaces (el enlace a mi web lo pongo yo encima del gancho).\nEl artículo: 700-1.000 palabras en Markdown (## para subtítulos, listas cuando ayuden), que desarrolle la misma idea con más profundidad y pasos prácticos, y que acabe con un párrafo que invite a la llamada de diagnóstico gratuita de " + GB_DUR + " minutos con 404 Growth.\n\nDevuelve SOLO un JSON: {\"titulo\":\"título del artículo, máximo 65 caracteres\",\"palabra_clave\":\"…\",\"descripcion\":\"meta descripción de 140-155 caracteres\",\"post\":\"texto del post de LinkedIn\",\"articulo\":\"Markdown del artículo, sin el título\"}", 5000);
  const title = str(out.titulo, 120) || pillar, now = Date.now(), slug = await blogSlug(env, title);
  if (pick) { try { await env.DB.prepare("UPDATE keywords SET status = 'en curso', notes = ?2, updated = ?3 WHERE id = ?1").bind(pick.id, ("artículo /blog/" + slug + (link ? " · enlaza a " + link : "")).slice(0, 600), now).run(); } catch (e) {} }   // v55: not used twice
  await env.DB.prepare("INSERT INTO lpost (slug, title, descr, kw, li, body, status, created, updated, auto) VALUES (?1, ?2, ?3, ?4, ?5, ?6, 'draft', ?7, ?7, ?8)")
    .bind(slug, title, str(out.descripcion, 200), str(out.palabra_clave, 120) || kw, liWeb(out.post).slice(0, 3000), String(out.articulo || "").slice(0, 40000), now, auto ? 1 : 0).run();
  return slug;
}
const LI_WEB = "Visita mi web: https://404growth.com";   // v65 (7 nov 2026): every LinkedIn post starts with a direct link to the web (only LinkedIn, not the blog)
const liWeb = (t) => { t = String(t || "").trim(); return !t || /404growth\.com/i.test(t.split("\n")[0]) ? t : LI_WEB + "\n\n" + t; };
const liLittle = (t) => String(t).replace(/[\\|{}@\[\]()<>*_~#]/g, "\\$&").replace(/\\#([\p{L}\p{N}]+)/gu, (m, w) => "{hashtag|\\#|" + w + "}");   // LinkedIn «little text»: reserved characters escaped, hashtags as hashtags
async function liPost(env, text) {
  const tk = await socJ(env, "li_tok"); if (!tk || tk.exp < Date.now()) { const e = new Error("noli"); e.code = "noli"; throw e; }
  const d = new Date(Date.now() - 62 * 864e5), ver = d.getUTCFullYear() + String(d.getUTCMonth() + 1).padStart(2, "0");
  const r = await fetch("https://api.linkedin.com/rest/posts", { method: "POST", headers: { authorization: "Bearer " + tk.t, "content-type": "application/json", "linkedin-version": ver, "x-restli-protocol-version": "2.0.0" },
    body: JSON.stringify({ author: "urn:li:person:" + tk.sub, commentary: liLittle(text), visibility: "PUBLIC", distribution: { feedDistribution: "MAIN_FEED", targetEntities: [], thirdPartyDistributionChannels: [] }, lifecycleState: "PUBLISHED", isReshareDisabledByAuthor: false }) });
  if (r.status !== 201) { const j = await r.json().catch(() => ({})); const e = new Error("LinkedIn: " + (j.message || r.status)); e.code = "lipost"; e.detail = j.message || String(r.status); throw e; }
  const id = r.headers.get("x-restli-id") || r.headers.get("x-linkedin-id") || "";
  return id ? "https://www.linkedin.com/feed/update/" + id + "/" : "https://www.linkedin.com/in/me/recent-activity/all/";
}

