  if (p === "li/unpublish" && m === "POST") { const b = await body(req); await DBq.prepare("UPDATE lpost SET status = 'draft', updated = ?1 WHERE slug = ?2").bind(now, str(b && b.slug, 120)).run(); return json({ ok: true }); }
