    if (pv && pv[1] !== "ejemplo" && await obIs(env, pv[1])) return go("/admin/obra/" + pv[1]);
    if (pv) return page(PAGES.portal.replace("/*PREVIEW*/", 'window.__PV="' + pv[1] + '";'));
